    String nombre = "A";
    String quienSoy() { return "A"; }
}

class B extends A {
    String nombre = "B";
    @Override String quienSoy() { return "B"; }
}

public class Principal {
    public static void main(String[] args) {
        A r = new B();
        System.out.println(r.nombre + r.quienSoy());
    }
}
